import { URL } from 'url'

/**
 * 将 Hoppscotch 请求对象 转换为 Postman 请求对象
 */
function convertRequest(req) {
  let urlParts
  try {
    urlParts = new URL(req.endpoint)
  } catch {
    urlParts = null
  }

  return {
    name: req.name,
    request: {
      method: req.method,
      header: (req.headers || []).map(h => ({
        key: h.key,
        value: h.value,
      })),
      body:
        req.body?.contentType === 'application/json'
          ? {
              mode: 'raw',
              raw: req.body.body || '',
              options: { raw: { language: 'json' } },
            }
          : undefined,
      url: urlParts
        ? {
            raw: req.endpoint,
            protocol: urlParts.protocol.replace(':', ''),
            host: urlParts.hostname.split('.'),
            port: urlParts.port || undefined,
            path: urlParts.pathname.split('/').filter(p => p.length > 0),
            query: (req.params || []).map(p => ({
              key: p.key,
              value: p.value,
            })),
          }
        : { raw: req.endpoint },
    },
    response: [],
  }
}

/**
 * 递归转换 Hoppscotch folders → Postman item
 */
function convertFolder(folder, allRequests) {
  return {
    name: folder.name,
    item: [
      ...(folder.requests || [])
        .map(id => {
            return convertRequest(id)
        //   const req = allRequests.find(r => r._id === id || r.v === id)
        //   return req ? convertRequest(req) : null
        })
        .filter(Boolean),
      ...(folder.folders || []).map(subFolder => convertFolder(subFolder, allRequests)),
    ],
  }
}

/**
 * Convert Hoppscotch JSON to Postman Collection v2.1
 * @param {Object} hoppscotchJson
 * @returns {Object} postmanJson
 */
export function convert(hoppscotchJson) {
  const rootItems = []
  // 处理 folders
  if (hoppscotchJson.folders?.length) {
    rootItems.push(...hoppscotchJson.folders.map(f => convertFolder(f, hoppscotchJson.requests)))
  }
  // 根目录下的 requests
  if (hoppscotchJson.requests?.length) {
    rootItems.push(...hoppscotchJson.requests.map(convertRequest))
  }

  return {
    info: {
      name: hoppscotchJson.name || 'Hoppscotch Import',
      schema: 'https://schema.getpostman.com/json/collection/v2.1.0/collection.json',
    },
    item: rootItems,
  }
}
